-- TEST ONLY. Tagged accounts and synthetic records; all jobs/data roll back.
begin;
create temporary table joining_review_results(result text);
do $$
declare host_id uuid; one_id uuid; two_id uuid; third_id uuid; cid uuid:=gen_random_uuid(); aid uuid:=gen_random_uuid();
  eid uuid:=gen_random_uuid(); ticket_id uuid:=gen_random_uuid(); free_order uuid:=gen_random_uuid(); paid_order uuid:=gen_random_uuid(); declined_order uuid:=gen_random_uuid(); mid uuid; saved_application uuid; denied boolean; result text; image_path text;
begin
  select u.id into strict host_id from auth.users u join public.profiles p on p.id=u.id where u.email='community.host@hat-test.invalid' and p.is_test_account and p.access_status='active';
  select u.id into strict one_id from auth.users u join public.profiles p on p.id=u.id where u.email='community.member.one@hat-test.invalid' and p.is_test_account and p.access_status='active';
  select u.id into strict two_id from auth.users u join public.profiles p on p.id=u.id where u.email='community.member.two@hat-test.invalid' and p.is_test_account and p.access_status='active';
  select u.id into strict third_id from auth.users u join public.profiles p on p.id=u.id where u.email='community.moderator@hat-test.invalid' and p.is_test_account and p.access_status='active';
  if exists(select 1 from public.user_roles where user_id in(host_id,one_id,two_id) and role='super_admin') then raise exception 'Only ordinary tagged rehearsal accounts are allowed'; end if;
  insert into public.communities(id,slug,name,description,community_type,status,created_by,join_policy) values(cid,'joining-test-'||cid,'[TEST] Joining controls','Synthetic rollback-only acceptance for Community joining and private review.','private','draft',host_id,'open');
  insert into public.community_memberships(community_id,user_id,role,status) values(cid,host_id,'owner','active');
  insert into public.community_host_applications(id,applicant_id,community_name,proposed_slug,category,purpose,intended_members,expected_members,admission_model,host_experience,safety_plan,guidelines_accepted_at,status,created_community_id,pilot_auto_draft)
  values(aid,host_id,'[TEST] Joining controls','joining-test-'||cid,'other','Synthetic rollback-only acceptance for Community joining and private review.','Tagged rehearsal members only.',20,'application_review','This is an isolated rollback-only rehearsal.','Synthetic records only. No real members, invitations or external emails are changed.',now(),'approved',cid,true);
  insert into public.community_pilot_publications(community_id,owner_id,application_id) values(cid,host_id,aid);
  update public.communities set status='published',join_policy='open' where id=cid;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform public.save_community_join_limit(cid,2,true);
  perform set_config('request.jwt.claim.sub',one_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',one_id,'role','authenticated')::text,true);
  result:=public.join_community_with_capacity(cid);if result<>'active' then raise exception 'Open Community did not admit available place';end if;
  denied:=false;begin perform public.save_community_join_limit(cid,10,true);exception when others then if sqlerrm like 'Only the Community owner%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Ordinary member changed capacity';end if;
  perform set_config('request.jwt.claim.sub',two_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',two_id,'role','authenticated')::text,true);
  result:=public.join_community_with_capacity(cid);if result<>'waitlisted' then raise exception 'Full Community did not offer waiting list';end if;
  result:=public.join_community_with_capacity(cid);if result<>'waitlisted' then raise exception 'Waiting-list retry was not idempotent';end if;
  if not exists(select 1 from public.list_community_join_limits(cid) where is_full and on_waiting_list and occupied_members=2) then raise exception 'Full state/own waiting-list projection is wrong';end if;
  denied:=false;begin perform public.list_community_waiting_members(cid);exception when others then if sqlerrm='Host access required' then denied:=true;else raise;end if;end;if not denied then raise exception 'Ordinary member read the Host waiting list';end if;
  execute 'reset role';
  if (select count(*) from public.community_join_waitlist where community_id=cid)<>1 then raise exception 'Duplicate waiting entry';end if;
  if not exists(select 1 from public.notification_jobs where user_id=host_id and dedupe_key='community-waitlist:'||cid||':'||two_id) then raise exception 'Host waiting-list email was not queued';end if;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  denied:=false;begin perform public.review_community_waiting_member(cid,two_id,'approve',null);exception when others then if sqlerrm like 'This Community is full%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Host approved beyond capacity';end if;
  perform public.save_community_join_limit(cid,3,true);perform public.review_community_waiting_member(cid,two_id,'approve',null);
  denied:=false;begin perform public.save_community_join_limit(cid,2,true);exception when others then if sqlerrm like 'The limit cannot be below%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Limit was lowered below occupied places';end if;
  execute 'reset role';
  if (select count(*) from public.community_memberships where community_id=cid and status='active')<>3 then raise exception 'Existing members were changed by a limit';end if;
  update public.community_memberships set status='removed' where community_id=cid and user_id=two_id;
  update public.communities set join_policy='approval' where id=cid;
  perform set_config('request.jwt.claim.sub',two_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',two_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  result:=public.join_community_with_capacity(cid);if result<>'requested' then raise exception 'Approval Community did not keep request pending';end if;
  execute 'reset role';select id into strict mid from public.community_memberships where community_id=cid and user_id=two_id;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  denied:=false;begin perform public.review_community_join_request(mid,'decline','no');exception when others then if sqlerrm like 'Add a short reason%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Short decline reason accepted';end if;
  perform public.review_community_join_request(mid,'decline','This test Community is for a different purpose.');
  perform set_config('request.jwt.claim.sub',one_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',one_id,'role','authenticated')::text,true);
  if exists(select 1 from public.community_join_decisions where membership_id=mid) then raise exception 'A member read another applicant decline reason';end if;
  perform set_config('request.jwt.claim.sub',two_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',two_id,'role','authenticated')::text,true);
  if not exists(select 1 from public.community_join_decisions where membership_id=mid) then raise exception 'Applicant cannot read own reason';end if;
  execute 'reset role';
  if not exists(select 1 from public.notification_jobs where user_id=two_id and payload->>'body' like '%different purpose%') then raise exception 'Private Community decision reason not queued';end if;

  image_path:='community_application/'||aid||'/'||host_id||'/rollback-test.webp';
  insert into public.application_proposal_media(owner_id,context_type,context_id,storage_path,mime_type,width,height,alt_text,status)
  values(host_id,'community_application',aid,image_path,'image/webp',1200,600,'Synthetic Community creation image','approved');
  perform set_config('request.jwt.claim.sub',one_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',one_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  if not public.can_read_community_creation_image(image_path) then raise exception 'Member cannot read approved creation image';end if;
  if not exists(select 1 from public.list_community_creation_images(cid) where storage_path=image_path and not icon_hidden and not cover_hidden) then raise exception 'Approved creation image not projected';end if;
  denied:=false;begin perform public.save_community_brand_with_creation_image(cid,'','ocean',p_remove_icon=>true);exception when others then if sqlerrm='Community owner required' then denied:=true;else raise;end if;end;if not denied then raise exception 'Non-owner removed Community image';end if;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);
  perform public.save_community_brand_with_creation_image(cid,'','ocean',p_remove_icon=>true,p_remove_cover=>true);
  if not exists(select 1 from public.list_community_creation_images(cid) where icon_hidden and cover_hidden) then raise exception 'Removing images did not suppress creation fallback';end if;
  execute 'reset role';update public.communities set status='archived' where id=cid;
  perform set_config('request.jwt.claim.sub',one_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',one_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  if public.can_read_community_creation_image(image_path) or exists(select 1 from public.list_community_creation_images(cid)) then raise exception 'Archived creation image exposed to ordinary member';end if;
  execute 'reset role';update public.communities set status='published' where id=cid;

  insert into public.events(id,slug,title,format,audience,status,starts_at,ends_at,registration_mode,capacity,created_by) values(eid,'joining-test-'||eid,'[TEST] Host review','virtual','public','published',now()+interval '7 days',now()+interval '7 days 1 hour','waitlist',2,host_id);
  insert into public.event_hosts(event_id,user_id,assigned_by) values(eid,host_id,host_id);
  insert into public.ticket_types(id,event_id,name,price_minor,currency,inventory_quantity,status) values(ticket_id,eid,'Test free place',0,'KES',2,'on_sale');
  insert into public.orders(id,user_id,event_id,status,processing_mode,currency,subtotal_minor,total_minor) values(free_order,one_id,eid,'pending_review','manual_review','KES',0,0),(paid_order,two_id,eid,'pending_review','manual_review','KES',100,100);
  insert into public.order_items(order_id,ticket_type_id,quantity,unit_price_minor,line_total_minor) values(free_order,ticket_id,1,0,0),(paid_order,ticket_id,1,100,100);
  insert into public.manual_payment_reviews(order_id) values(free_order),(paid_order);
  insert into public.registration_requests(event_id,user_id,order_id,status) values(eid,one_id,free_order,'pending_review'),(eid,two_id,paid_order,'pending_review');
  if not exists(select 1 from public.notification_jobs where user_id=host_id and dedupe_key='event-registration-review:'||free_order||':'||host_id) then raise exception 'Event Host was not notified of request';end if;
  perform set_config('request.jwt.claim.sub',one_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',one_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  denied:=false;begin perform public.list_host_event_requests(eid);exception when others then if sqlerrm='Event Host access required' then denied:=true;else raise;end if;end;if not denied then raise exception 'Ordinary guest read Host requests';end if;
  denied:=false;begin perform public.review_host_event_request(free_order,'approve',null);exception when others then if sqlerrm='Event Host access required' then denied:=true;else raise;end if;end;if not denied then raise exception 'Guest approved own booking';end if;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);
  if (select count(*) from public.list_host_event_requests(eid))<>1 then raise exception 'Host free-only projection includes payment records';end if;
  denied:=false;begin perform public.review_host_event_request(paid_order,'approve',null);exception when others then if sqlerrm like 'Only pending free places%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Host reviewed paid booking';end if;
  perform public.review_host_event_request(free_order,'approve',null);
  denied:=false;begin perform public.review_host_event_request(free_order,'approve',null);exception when others then if sqlerrm like 'Only pending free places%' then denied:=true;else raise;end if;end;if not denied then raise exception 'Duplicate review accepted';end if;
  execute 'reset role';
  if not exists(select 1 from public.event_memberships where event_id=eid and user_id=one_id and status='confirmed') then raise exception 'Free approval did not create pass';end if;
  if not exists(select 1 from public.notification_jobs where user_id=host_id and dedupe_key like 'event-host-place:'||eid||':%') then raise exception 'Confirmed join did not notify Host';end if;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform set_config('request.jwt.claim.sub',third_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',third_id,'role','authenticated')::text,true);
  perform public.join_full_event_waitlist(eid);
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);
  if (select count(*) from public.list_host_event_waiting_members(eid))<>1 then raise exception 'Waiting-list entry not visible to Host';end if;
  execute 'reset role';
  if not exists(select 1 from public.notification_jobs where user_id=host_id and dedupe_key like 'event-host-waitlist:%' and payload->>'href'='/events/joining-test-'||eid||'/host#guest-requests') then raise exception 'Waiting-list Host notice missing';end if;

  update public.registration_requests set status='cancelled' where event_id=eid and user_id=third_id;
  update public.events set capacity=3 where id=eid;
  update public.ticket_types set inventory_quantity=3 where id=ticket_id;
  insert into public.orders(id,user_id,event_id,status,processing_mode,currency,subtotal_minor,total_minor) values(declined_order,third_id,eid,'pending_review','manual_review','KES',0,0);
  insert into public.order_items(order_id,ticket_type_id,quantity,unit_price_minor,line_total_minor) values(declined_order,ticket_id,1,0,0);
  insert into public.manual_payment_reviews(order_id) values(declined_order);
  update public.registration_requests set status='pending_review',order_id=declined_order where event_id=eid and user_id=third_id;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  perform public.review_host_event_request(declined_order,'reject','This test session is for a different audience.');
  execute 'reset role';
  if not exists(select 1 from public.notification_jobs where user_id=third_id and payload->>'body' like '%different audience%') then raise exception 'Event private decline reason not queued';end if;
  perform set_config('request.jwt.claim.sub',host_id::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',host_id,'role','authenticated')::text,true);execute 'set local role authenticated';
  saved_application:=public.save_community_host_application_with_limits(null,'Joining rehearsal '||left(aid::text,8),'other','An isolated rehearsal of Community creation and member limit saving.','Only tagged test accounts for this rollback rehearsal.',20,'open_request','Isolated host acceptance rehearsal.','Synthetic test records only. No real members or emails are affected.',null,true,'global',null,10,true);
  execute 'reset role';
  if not exists(select 1 from public.community_application_join_limits where application_id=saved_application and maximum_members=10 and waiting_list_enabled) then raise exception 'Creation form did not save optional member limit';end if;
  perform set_config('request.jwt.claim.sub','',true);perform set_config('request.jwt.claims','{"role":"anon"}',true);execute 'set local role anon';
  denied:=false;begin perform public.list_host_event_requests(eid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Anonymous Host access allowed';end if;
  denied:=false;begin perform public.list_community_join_limits(cid);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Anonymous membership limits allowed';end if;
  execute 'reset role';
  insert into joining_review_results values('PASS: optional Community limits include Host; creation wrapper saves limits; full/waitlisted/idempotent joins; member/anon denial; below-occupied/over-capacity denial; waiting approval; private Community/event reasons and Host queues; free-only event review, duplicate denial, pass creation and waiting-list Host visibility; approved creation-image projection, archived denial, owner-only removal and suppressed fallback. All synthetic data and emails rolled back.');
end $$;
select * from joining_review_results;
rollback;
